/// <summary>
/// Service class for the label capture render batch. Renders pending captured ZPL staging rows to
/// PNG images and attaches them to the originating Work record. Rows are picked up across companies
/// and processed one at a time in the row's company so a failure isolates to that row.
/// </summary>
public class AAXWHSLabelCaptureRenderService extends SysOperationServiceBase
{
}

Method.Source:
/// <summary>
/// Renders and attaches all currently <c>Pending</c> captured labels across every legal entity.
/// </summary>
/// <param name = "_contract">The data contract containing the chunk size and maximum retry count.</param>
public void process(AAXWHSLabelCaptureRenderContract _contract)
{
    int chunkSize  = _contract.parmChunkSize() > 0 ? _contract.parmChunkSize() : 50;
    int maxRetries = _contract.parmMaxRetries() > 0 ? _contract.parmMaxRetries() : 3;

    // Collect the pending rows per company before any work runs
    Map companyToRecIds = this.collectPendingRecIdsByCompany();

    MapEnumerator companyEnumerator = companyToRecIds.getEnumerator();
    while (companyEnumerator.moveNext())
    {
        this.processCompany(companyEnumerator.currentKey(), companyEnumerator.currentValue(), chunkSize, maxRetries);
    }
}

/// <summary>
/// Renders and attaches the currently pending captured rows immediately after a label print
/// transaction commits. Reuses the batch pipeline, and any row it cannot complete stays pending
/// for the scheduled render batch. Errors are swallowed so the warehouse flow is never disrupted.
/// </summary>
public static void renderPendingInline()
{
    try
    {
        new AAXWHSLabelCaptureRenderService().process(new AAXWHSLabelCaptureRenderContract());
    }
    catch
    {
        // Leftover rows remain pending for the scheduled render batch
    }
}

/// <summary>
/// Processes the captured rows of one legal entity inside a <c>changecompany</c> block so the
/// parameter check, document type creation, and attachments run in the row's company.
/// </summary>
/// <param name = "_dataAreaId">The legal entity to switch into.</param>
/// <param name = "_recIds">The staging RecIds captured in that company, in pickup order.</param>
/// <param name = "_chunkSize">The maximum number of rows per processing pass.</param>
/// <param name = "_maxRetries">The maximum number of render attempts before a row becomes Poison.</param>
private void processCompany(DataAreaId _dataAreaId, List _recIds, int _chunkSize, int _maxRetries)
{
    changecompany (_dataAreaId)
    {
        // Re-check the parameter per company, which also turns off an expired toggle
        if (!WHSParameters::find().aaxIsPreviewToWorkAttachmentEnabled())
        {
            return;
        }

        // Create the document type in this company if it is missing
        AAXWHSLabelAttachmentService::ensureDocuType();

        this.processCompanyRows(_recIds, _chunkSize, _maxRetries);
    }
}

/// <summary>
/// Collects the RecIds of all pending staging rows across companies, ordered by RecId, and groups
/// them by <c>DataAreaId</c>.
/// </summary>
/// <returns>A <c>Map</c> of <c>DataAreaId</c> to a <c>List</c> of staging RecIds.</returns>
private Map collectPendingRecIdsByCompany()
{
    Map                         companyToRecIds = new Map(Types::String, Types::Class);
    AAXWHSLabelCaptureStaging   staging;

    while select crosscompany RecId, DataAreaId from staging
        order by RecId asc
        where staging.Status == AAXWHSLabelCaptureStatus::Pending
    {
        List recIds;

        if (companyToRecIds.exists(staging.DataAreaId))
        {
            recIds = companyToRecIds.lookup(staging.DataAreaId);
        }
        else
        {
            recIds = new List(Types::Int64);
            companyToRecIds.insert(staging.DataAreaId, recIds);
        }

        recIds.addEnd(staging.RecId);
    }

    return companyToRecIds;
}

/// <summary>
/// Processes the supplied staging RecIds in the current company in chunk-sized passes.
/// Each row is processed independently so a failure isolates to that row.
/// </summary>
/// <param name = "_recIds">The staging RecIds to process, in pickup order.</param>
/// <param name = "_chunkSize">The maximum number of rows to process per pass.</param>
/// <param name = "_maxRetries">The maximum number of render attempts before a row becomes Poison.</param>
private void processCompanyRows(List _recIds, int _chunkSize, int _maxRetries)
{
    ListEnumerator recIdEnumerator = _recIds.getEnumerator();
    int            processedInChunk;

    while (recIdEnumerator.moveNext())
    {
        RecId stagingRecId = recIdEnumerator.current();

        // Each row runs in its own try/catch so a failure only updates that row
        try
        {
            this.processRow(stagingRecId, _maxRetries);
        }
        catch
        {
            this.markRowError(stagingRecId, _maxRetries, AAXWHSLabelCaptureRenderService::lastErrorText());
        }

        // Bound the number of rows handled per pass
        processedInChunk++;
        if (processedInChunk >= _chunkSize)
        {
            processedInChunk = 0;
        }
    }
}

/// <summary>
/// Renders and attaches a single captured label and advances its status. State transitions use
/// short retryable transactions, and rendering and attachment run outside any transaction so the
/// caller can isolate failures.
/// </summary>
/// <param name = "_stagingRecId">The RecId of the staging row.</param>
/// <param name = "_maxRetries">The maximum number of render attempts before a row becomes Poison.</param>
private void processRow(RecId _stagingRecId, int _maxRetries)
{
    // Claim the row before doing any work
    if (!this.markRowProcessing(_stagingRecId))
    {
        // The row was claimed by another pass or is no longer pending
        return;
    }

    AAXWHSLabelCaptureStaging staging = AAXWHSLabelCaptureStaging::find(_stagingRecId);
    if (!staging)
    {
        return;
    }

    // A Work record that no longer exists completes the row with a note
    WHSWorkTable workTable = WHSWorkTable::find(staging.WorkId);
    if (!workTable)
    {
        this.markRowDone(_stagingRecId, "@AAXWarehouseTools:WorkNoLongerExists");
        return;
    }

    // The render and attach steps are shared with the inline capture path
    AAXWHSLabelCaptureRenderService::renderAndAttach(
        workTable,
        staging.FinalZpl,
        staging.ZplHash,
        staging.WorkId,
        staging.LayoutId,
        staging.Dpmm,
        staging.WidthMm,
        staging.HeightMm);

    this.markRowDone(_stagingRecId, '');
}

/// <summary>
/// Renders one captured ZPL and attaches the resulting images to its Work record. Shared by the
/// render batch and the inline capture path. Skips the label when an attachment with the same
/// hash already exists, and throws when the ZPL renders no image so the caller can record the
/// failure. Row state is not changed.
/// </summary>
/// <param name = "_work">The Work record to attach to.</param>
/// <param name = "_finalZpl">The captured, token-substituted ZPL.</param>
/// <param name = "_hash">The SHA-256 hash of the ZPL, used for the duplicate check and the attachment notes.</param>
/// <param name = "_workId">The Work id used in the file name.</param>
/// <param name = "_layoutId">The layout id used in the file name; may be empty.</param>
/// <param name = "_dpmm">The render density, or 0 to use the size declared in the ZPL with the parameter fallback.</param>
/// <param name = "_widthMm">The render width in millimeters, or 0.</param>
/// <param name = "_heightMm">The render height in millimeters, or 0.</param>
public static void renderAndAttach(
    WHSWorkTable    _work,
    str             _finalZpl,
    AAXWHSZplHash   _hash,
    WHSWorkId       _workId,
    str             _layoutId = '',
    int             _dpmm     = 0,
    real            _widthMm  = 0,
    real            _heightMm = 0)
{
    if (!_work.RecId || !_finalZpl)
    {
        return;
    }

    // Skip labels that are already attached to the Work record
    if (AAXWHSLabelAttachmentService::hasAttachmentWithHash(_work, _hash))
    {
        return;
    }

    List pngs = AAXZplRenderService::renderToPngList(_finalZpl, _dpmm, _widthMm, _heightMm);

    if (!pngs || pngs.elements() == 0)
    {
        throw error("@AAXWarehouseTools:RenderProducedNoImage");
    }

    // Attaching requires the document type to exist in this company
    AAXWHSLabelAttachmentService::ensureDocuType();

    str             timestamp = AAXWHSLabelCaptureRenderService::timestampForFileName();
    int             seq;
    ListEnumerator  pngEnumerator = pngs.getEnumerator();

    while (pngEnumerator.moveNext())
    {
        seq++;
        container png = pngEnumerator.current();

        str fileName = AAXWHSLabelCaptureRenderService::buildFileName(
            _workId, _layoutId, timestamp, seq);

        AAXWHSLabelAttachmentService::attachPng(_work, png, fileName, _hash);
    }
}

/// <summary>
/// Moves a pending row to Processing in a short retryable transaction.
/// </summary>
/// <param name = "_stagingRecId">The RecId of the staging row.</param>
/// <returns>True if this call moved the row to Processing; otherwise false.</returns>
private boolean markRowProcessing(RecId _stagingRecId)
{
    boolean claimed = false;

    #OCCRetryCount

    try
    {
        AAXWHSLabelCaptureStaging staging;

        ttsbegin;
        select forupdate staging
            where staging.RecId == _stagingRecId
               && staging.Status == AAXWHSLabelCaptureStatus::Pending;
        if (staging)
        {
            staging.Status = AAXWHSLabelCaptureStatus::Processing;
            staging.update();
            claimed = true;
        }
        ttscommit;
    }
    catch (Exception::Deadlock)
    {
        retry;
    }
    catch (Exception::UpdateConflict)
    {
        if (appl.ttsLevel() == 0)
        {
            if (xSession::currentRetryCount() >= #RetryNum)
            {
                throw Exception::UpdateConflictNotRecovered;
            }
            else
            {
                retry;
            }
        }
        else
        {
            throw;
        }
    }

    return claimed;
}

/// <summary>
/// Moves a row to the terminal Done status with an optional note and the processed timestamp,
/// in a short retryable transaction.
/// </summary>
/// <param name = "_stagingRecId">The RecId of the staging row.</param>
/// <param name = "_note">An optional note stored on the row; may be empty.</param>
private void markRowDone(RecId _stagingRecId, str _note)
{
    #OCCRetryCount

    try
    {
        AAXWHSLabelCaptureStaging staging;

        ttsbegin;
        select forupdate staging
            where staging.RecId == _stagingRecId;
        if (staging)
        {
            staging.Status              = AAXWHSLabelCaptureStatus::Done;
            staging.ErrorMessage        = _note;
            staging.ProcessedDateTime   = DateTimeUtil::utcNow();
            staging.update();
        }
        ttscommit;
    }
    catch (Exception::Deadlock)
    {
        retry;
    }
    catch (Exception::UpdateConflict)
    {
        if (appl.ttsLevel() == 0)
        {
            if (xSession::currentRetryCount() >= #RetryNum)
            {
                throw Exception::UpdateConflictNotRecovered;
            }
            else
            {
                retry;
            }
        }
        else
        {
            throw;
        }
    }
}

/// <summary>
/// Records a render or attachment failure on a single row. Increments the retry count, stores
/// the error text, and sets the status to Error, or to Poison when the retry limit is reached.
/// </summary>
/// <param name = "_stagingRecId">The RecId of the staging row.</param>
/// <param name = "_maxRetries">The maximum number of render attempts before the row becomes Poison.</param>
/// <param name = "_errorText">The failure text to store, truncated to the field size.</param>
private void markRowError(RecId _stagingRecId, int _maxRetries, str _errorText)
{
    #OCCRetryCount

    try
    {
        AAXWHSLabelCaptureStaging staging;

        ttsbegin;
        select forupdate staging
            where staging.RecId == _stagingRecId;
        if (staging)
        {
            staging.RetryCount       = staging.RetryCount + 1;
            staging.ErrorMessage     = subStr(_errorText, 1, 1000);
            staging.ProcessedDateTime = DateTimeUtil::utcNow();
            staging.Status           = staging.RetryCount >= _maxRetries
                ? AAXWHSLabelCaptureStatus::Poison
                : AAXWHSLabelCaptureStatus::Error;
            staging.update();
        }
        ttscommit;
    }
    catch (Exception::Deadlock)
    {
        retry;
    }
    catch (Exception::UpdateConflict)
    {
        if (appl.ttsLevel() == 0)
        {
            if (xSession::currentRetryCount() >= #RetryNum)
            {
                throw Exception::UpdateConflictNotRecovered;
            }
            else
            {
                retry;
            }
        }
        else
        {
            throw;
        }
    }
}

/// <summary>
/// Gets the most recent Infolog error text for storing on a failed row.
/// </summary>
/// <returns>The error text, or a generic message when none is available.</returns>
private static str lastErrorText()
{
    str text = infolog.text();

    if (!text)
    {
        text = "@AAXWarehouseTools:RenderFailed";
    }

    return text;
}

/// <summary>
/// Builds the UTC timestamp segment of the attachment file name in the format yyyyMMdd_HHmmss.
/// </summary>
/// <returns>The formatted timestamp.</returns>
private static str timestampForFileName()
{
    utcDateTime now = DateTimeUtil::utcNow();

    return strFmt('%1%2%3_%4%5%6',
        num2Str0(DateTimeUtil::year(now), 4),
        num2Str0(DateTimeUtil::month(now), 2),
        num2Str0(DateTimeUtil::day(now), 2),
        num2Str0(DateTimeUtil::hour(now), 2),
        num2Str0(DateTimeUtil::minute(now), 2),
        num2Str0(DateTimeUtil::second(now), 2));
}

/// <summary>
/// Builds the attachment file name from the Work id, the layout id, the timestamp, and the label
/// sequence number. The layout id segment is omitted when it is empty.
/// </summary>
/// <param name = "_workId">The Work id.</param>
/// <param name = "_layoutId">The layout id; may be empty.</param>
/// <param name = "_timestamp">The formatted UTC timestamp segment.</param>
/// <param name = "_seq">The 1-based label block sequence number.</param>
/// <returns>The file name including the .png extension.</returns>
private static str buildFileName(WHSWorkId _workId, str _layoutId, str _timestamp, int _seq)
{
    str fileName;

    if (_layoutId)
    {
        fileName = strFmt('%1_%2_%3_%4', _workId, _layoutId, _timestamp, _seq);
    }
    else
    {
        fileName = strFmt('%1_%2_%3', _workId, _timestamp, _seq);
    }

    return fileName + '.png';
}
